import type { ChangeEvent, FunctionComponent } from 'react'
import React, { useState } from 'react'
import * as icons from '../icons'
import TextInput from '../TextInput/TextInput'
import Tooltip from '../Tooltip/Tooltip'

export default {
  title: 'Components/Icons',
}

export function Icons(): JSX.Element {
  const [query, setQuery] = useState('')

  const handleChange = (
    event: ChangeEvent<HTMLInputElement | HTMLTextAreaElement>,
  ) => {
    setQuery(event.target.value)
  }

  return (
    <div className="space-y-8">
      <div className="w-64">
        <TextInput
          defaultValue=""
          helperText="You can use regex too!"
          label="Search"
          onChange={handleChange}
          size="small"
          type="search"
        />
      </div>
      <div className="grid grid-flow-row grid-cols-6 gap-4 xl:grid-cols-16 lg:grid-cols-12 md:grid-cols-8">
        {Object.entries(icons as Record<string, FunctionComponent>)
          .filter(([name]) => {
            try {
              return name.match(new RegExp(`.*${query}.*`, 'i'))
            } catch {
              return true
            }
          })
          .map(([name, Icon]) => (
            <div className="w-8 h-8" key={name}>
              <Tooltip arrow title={name}>
                <Icon />
              </Tooltip>
            </div>
          ))}
      </div>
    </div>
  )
}
